SECTIONS = {"ru": RU, "en": EN, "uz": UZ}


def check_numbers():
    """Recompute every number quoted in the text."""
    import math
    sig = lambda z: 1 / (1 + math.exp(-z))
    close = lambda a, b, d=4: abs(round(a, d) - b) < 1e-9
    prods = [w * x for w, x in zip(W, X)]
    assert prods == [1, 1, 0.75] and sum(prods) == 2.75
    z = sum(prods) + B
    assert z == 2 and close(sig(z), 0.8808) and close(math.tanh(z), 0.9640) and close(math.exp(-2), 0.1353)
    assert close(sig(1.25), 0.7773)
    nw, nx = math.sqrt(sum(v * v for v in W)), math.sqrt(sum(v * v for v in X))
    assert sum(v * v for v in W) == 1.3125 and close(nw, 1.1456) and close(nx, 3.7417)
    cos = 2.75 / (nw * nx)
    assert close(cos, 0.6415) and round(math.degrees(math.acos(cos)), 1) == 50.1 and round(z / nw, 3) == 1.746
    assert 1.2 * 60 + 5 * 2 - 2 * 5 + 10 == 82
    zc = 3 * 0.4 + 0.8 * 2 - 0.3 * 5 - 2
    assert abs(zc + 0.7) < 1e-12 and close(sig(-0.7), 0.3318)
    assert -1 * 2 + 0.5 * -1 + 1 * 3 + 0.5 == 1
    a = sig(z)
    g = [a * v for v in X]
    assert [round(v, 4) for v in g] == [1.7616, -0.8808, 2.6424]
    w2 = [w - 0.1 * gi for w, gi in zip(W, g)]
    b2 = B - 0.1 * a
    assert [round(v, 4) for v in w2] == [0.3238, -0.9119, -0.0142] and round(b2, 4) == -0.8381
    z2 = sum(p * q for p, q in zip(w2, X)) + b2
    assert close(z2, 0.6788) and close(sig(z2), 0.6635)
    assert close(-math.log(1 - a), 2.1269) and close(-math.log(1 - sig(z2)), 1.0891)
    return True


if __name__ == "__main__":
    print("numbers ok" if check_numbers() else "")
